mkdir -p tests/window && cat > tests/window/window.test.ts <<'EOF'
import { describe, expect, test } from 'vitest';
import {
	asc,
	cumeDist,
	currentRow,
	denseRank,
	desc,
	firstValue,
	following,
	lag,
	lastValue,
	lead,
	nthValue,
	ntile,
	percentRank,
	preceding,
	range,
	rank,
	rowNumber,
	rows,
	unboundedFollowing,
	unboundedPreceding,
	windowAvg,
	windowCount,
	windowMax,
	windowMin,
	windowSum,
} from '~/index.ts';
import { drizzle as mysqlDrizzle } from '~/mysql2';
import { mysqlTable, int as mysqlInt, varchar } from '~/mysql-core';
import { drizzle as pgDrizzle } from '~/node-postgres';
import { integer, pgTable, text } from '~/pg-core';
import { drizzle as sqliteDrizzle } from '~/better-sqlite3';
import { integer as sqliteInt, sqliteTable } from '~/sqlite-core';
import { PgDialect } from '~/pg-core/dialect.ts';

const employees = pgTable('employees', {
	id: integer('id').notNull(),
	dept: text('dept').notNull(),
	salary: integer('salary'),
});

const db = pgDrizzle.mock();
const dialect = new PgDialect();
const q = (s: Parameters<PgDialect['sqlToQuery']>[0]) => dialect.sqlToQuery(s);

describe('window functions', () => {
	test('function names', () => {
		expect(q(rowNumber().over()).sql).toBe('row_number() over ()');
		expect(q(rank().over()).sql).toBe('rank() over ()');
		expect(q(denseRank().over()).sql).toBe('dense_rank() over ()');
		expect(q(percentRank().over()).sql).toBe('percent_rank() over ()');
		expect(q(cumeDist().over()).sql).toBe('cume_dist() over ()');
		expect(q(ntile(4).over()).sql).toBe('ntile(4) over ()');
		expect(q(firstValue(employees.salary).over()).sql).toBe('first_value("employees"."salary") over ()');
		expect(q(lastValue(employees.salary).over()).sql).toBe('last_value("employees"."salary") over ()');
		expect(q(nthValue(employees.salary, 2).over()).sql).toBe('nth_value("employees"."salary", 2) over ()');
		expect(q(windowSum(employees.salary).over()).sql).toBe('sum("employees"."salary") over ()');
		expect(q(windowAvg(employees.salary).over()).sql).toBe('avg("employees"."salary") over ()');
		expect(q(windowMin(employees.salary).over()).sql).toBe('min("employees"."salary") over ()');
		expect(q(windowMax(employees.salary).over()).sql).toBe('max("employees"."salary") over ()');
		expect(q(windowCount().over()).sql).toBe('count(*) over ()');
		expect(q(windowCount(employees.id).over()).sql).toBe('count("employees"."id") over ()');
	});

	test('lag / lead optional args, no params for numbers', () => {
		expect(q(lag(employees.salary).over())).toEqual({ sql: 'lag("employees"."salary") over ()', params: [] });
		expect(q(lead(employees.salary, 0).over())).toEqual({ sql: 'lead("employees"."salary", 0) over ()', params: [] });
		expect(q(lag(employees.salary, 2, 0).over())).toEqual({
			sql: 'lag("employees"."salary", 2, 0) over ()',
			params: [],
		});
		expect(q(lead(employees.dept, undefined, 'none').over())).toEqual({
			sql: 'lead("employees"."dept", 1, $1) over ()',
			params: ['none'],
		});
	});

	test('inline spec and frames', () => {
		expect(
			q(
				windowSum(employees.salary).over({
					partitionBy: employees.dept,
					orderBy: [asc(employees.id), desc(employees.salary)],
					frame: rows({ from: unboundedPreceding, to: currentRow }),
				}),
			).sql,
		).toBe(
			'sum("employees"."salary") over (partition by "employees"."dept" order by "employees"."id" asc, "employees"."salary" desc rows between unbounded preceding and current row)',
		);
		expect(q(windowAvg(employees.salary).over({ frame: range({ from: preceding(3), to: following(0) }) })))
			.toEqual({ sql: 'avg("employees"."salary") over (range between 3 preceding and 0 following)', params: [] });
		expect(q(windowMax(employees.salary).over({ frame: rows({ from: currentRow, to: unboundedFollowing }) })).sql)
			.toBe('max("employees"."salary") over (rows between current row and unbounded following)');
	});

	test('named windows', () => {
		const query = db.select({ id: employees.id, r: rank().over('w') }).from(employees)
			.window('w', { partitionBy: employees.dept, orderBy: desc(employees.salary) })
			.orderBy(employees.id)
			.toSQL();
		expect(query.sql).toBe(
			'select "id", rank() over "w" from "employees" window "w" as (partition by "employees"."dept" order by "employees"."salary" desc) order by "employees"."id"',
		);
	});

	test('window on other dialects', () => {
		const m = mysqlTable('t', { id: mysqlInt('id'), name: varchar('name', { length: 10 }) });
		expect(
			mysqlDrizzle.mock().select({ r: rowNumber().over('a') }).from(m).window('a', { orderBy: m.id }).window('b', {})
				.toSQL().sql,
		).toBe('select row_number() over `a` from `t` window `a` as (order by `t`.`id`), `b` as ()');
		const s = sqliteTable('t', { id: sqliteInt('id') });
		expect(
			sqliteDrizzle.mock().select({ r: rowNumber().over('a') }).from(s).window('a', { orderBy: s.id }).toSQL().sql,
		).toBe('select row_number() over "a" from "t" window "a" as (order by "t"."id")');
	});

	test('validation', () => {
		expect(() => ntile(0)).toThrow(/ntile.*0/);
		expect(() => ntile(1.5)).toThrow(/ntile.*1\.5/);
		expect(() => nthValue(employees.salary, -1)).toThrow(/nthValue.*-1/);
		expect(() => db.select().from(employees).window('', {})).toThrow(/non-empty/);
		expect(() => db.select().from(employees).window('  ', {})).toThrow(/whitespace/);
		expect(() => rows({ from: currentRow, to: preceding(1) })).toThrow(/from/);
		expect(() => range({ from: following(2), to: following(1) })).toThrow(/from/);
		expect(() => preceding(-1)).toThrow(/preceding/);
		expect(() => following(0.5)).toThrow(/following/);
	});
});
EOF
